import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inpStr = scanner.nextLine();

        while (inpStr.substring(1, inpStr.length() - 1).contains("dot")) {
            int dotIndex = inpStr.substring(1).indexOf("dot") + 1;
            inpStr = inpStr.substring(0, dotIndex) + "." + inpStr.substring(dotIndex + 3);
        }

        int atIndex = inpStr.substring(1).indexOf("at") + 1;
        inpStr = inpStr.substring(0, atIndex) + "@" + inpStr.substring(atIndex + 2);
        System.out.println(inpStr);
    }
}
